        return '\n'.join(results)

    # Parse all queries
    queries = []
    for i in range(1, t + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                queries.append((int(parts[0]), int(parts[1])))
            else:
                queries.append((0, 0))
        else:
            queries.append((0, 0))

    # Maximum distance any ant can travel
    max_dist = n // 4

    # Key insight: The simulation can be done more directly
    # Each group of 4 ants at distance d spreads to adjacent cells
    # This is essentially simulating how the ant "wave" moves

    # Use BFS simulation by distance levels
    ans = {(0, 0): n}

    # Process cells level by level (by Manhattan distance from origin)
    # This ensures we process all ants at distance d before any at distance d+1
    layer_by_dist = {0: [(0, 0)]}
    dist_map = {0: 0}

    d = 0
    while d <= max_dist:
        # Get all cells at distance d
        current_layer = layer_by_dist[d]

        # Prepare next layer
        next_layer = []
        next_ans = {}

        for (x, y) in current_layer:
            cnt = ans.get((x, y), 0)

            if cnt == 0:
                continue

            # Calculate how many groups of 4 can be formed
            groups = cnt // 4
            remainder = cnt % 4

            # Each group of 4 spreads to 4 neighbors
            if groups > 0:
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = x + dx, y + dy

                    # Check if this position has already been processed at this distance
                    if abs(nx) + abs(ny) > max_dist:
                        continue

                    # Add ants to the neighbor
                    next_ans[(nx, ny)] = next_ans.get((nx, ny), 0) + groups

                    # Add to next layer if not already there
                    neighbor_dist = abs(nx) + abs(ny)
                    if neighbor_dist >= d:
                        next_layer.append((nx, ny))

        # Update remaining ants at current positions
        for (x, y) in current_layer:
            cnt = ans.get((x, y), 0)
            if cnt >= 4:
                remainder = cnt % 4
                next_ans[(x, y)] = remainder

        # Prepare for next iteration
        ans = next_ans

        # Only continue if we haven't exceeded max distance
        d += 1
        if d > max_dist:
            break

        # Get cells at distance d for next iteration
        unique_cells = set()
        for cell in next_layer:
            dist = abs(cell[0]) + abs(cell[1])
            if dist == d:
                unique_cells.add(cell)

        if not unique_cells or d > max_dist:
            break
        layer_by_dist[d] = list(unique_cells)

        for cell in unique_cells:
            dist_map[cell] = d

    # Answer queries
    results = []
    for qx, qy in queries:
        if abs(qx) + abs(qy) > max_dist:
            results.append("0")
        else:
            results.append(str(ans.get((qx, qy), 0)))

    return '\n'.join(results)

