    n, m = map(int, lines[0].split())

    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]
    rev_adj = [[] for _ in range(num_nodes)]

    def get_node(l):
        if l > 0:
            return 2 * (l - 1)
        else:
            return 2 * (abs(l) - 1) + 1

    def get_neg_node(l):
        if l > 0:
            return 2 * (l - 1) + 1
        else:
            return 2 * (abs(l) - 1)

    for line in lines[1:n+1]:
        parts = list(map(int, line.split()))
        k = parts[0]
        literals = parts[1:]

        if k <= 0:
            continue

        if k == 1:
            l = literals[0]
            adj[get_neg_node(l)].append(get_node(l))
            rev_adj[get_node(l)].append(get_neg_node(l))
        else:
            for i in range(k - 1):
                u = get_neg_node(literals[i])
                v = get_node(literals[i + 1])
                if len(adj[u]) < 10000:
                    adj[u].append(v)
                    rev_adj[v].append(u)

    visited = [False] * num_nodes
    order = []

    def dfs1(v):
        visited[v] = True
        for neighbor in adj[v]:
            if not visited[neighbor]:
                dfs1(neighbor)
        order.append(v)

    stack = []
    for i in range(num_nodes):
        if not visited[i]:
            dfs1(i)

    visited = [False] * num_nodes
    scc_id = [-1] * num_nodes
    scc_count = 0

    def dfs2(v):
        visited[v] = True
        scc_id[v] = scc_count
        for neighbor in rev_adj[v]:
            if not visited[neighbor]:
                dfs2(neighbor)

    for node in reversed(order):
        if not visited[node]:
            scc_count += 1
            dfs2(node)

    result = []
    for var in range(1, m + 1):
        x_node = get_node(var)
        not_x_node = get_neg_node(var)

        if scc_id[x_node] == scc_id[not_x_node]:
            return "NO\n"

        result.append('1' if scc_id[x_node] < scc_id[not_x_node] else '0')

    return "YES\n" + "".join(result) + "\n"

