def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list for the graph
    graph = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        graph[u].append(v)
        graph[v].append(u)

    # Find connected components using BFS
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            # BFS to find all nodes in this component
            queue = [i]
            visited[i] = True
            size = 0
            head = 0
            while head < len(queue):
                node = queue[head]
                head += 1
                size += 1
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    # Generate all lucky numbers up to n
    lucky_numbers = []

    def generate_lucky_numbers(current):
        if current == 0:
            return
        if current > n:
            return
        lucky_numbers.append(current)

        if current * 10 + 4 <= n:
            generate_lucky_numbers(current * 10 + 4)
        if current * 10 + 7 <= n:
            generate_lucky_numbers(current * 10 + 7)

    # Start with single digits 4 and 7
    generate_lucky_numbers(4)
    generate_lucky_numbers(7)

    lucky_numbers.sort()

    # DP to find minimum number of components needed to reach each lucky sum
    # dp[s] = minimum number of components whose sizes sum to s
    dp = {0: 0}

    for size in component_sizes:
        # Create new states from current states
        new_dp = dp.copy()
        for s, count in dp.items():
            new_s = s + size
            if new_s <= n:
                new_count = count + 1
                if new_s not in new_dp or new_count < new_dp[new_s]:
                    new_dp[new_s] = new_count
        dp = new_dp

    # Find minimum roads needed: min(dp[lucky] - 1) for all lucky lucky numbers
    min_roads = float('inf')
    for lucky in lucky_numbers:
        if lucky in dp:
            roads_needed = dp[lucky] - 1
            min_roads = min(min_roads, roads_needed)

    if min_roads == float('inf'):
        return "-1\n"
    else:
        return f"{min_roads}\n"
